import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
class GiftItem{final String id,name,emoji;final int price;const GiftItem({required this.id,required this.name,required this.emoji,required this.price});}
const gifts=<GiftItem>[GiftItem(id:'rose',name:'وردة',emoji:'🌹',price:100),GiftItem(id:'heart',name:'قلب',emoji:'❤️',price:500),GiftItem(id:'diamond',name:'ماسة',emoji:'💎',price:1000),GiftItem(id:'crown',name:'تاج',emoji:'👑',price:5000),GiftItem(id:'dragon',name:'تنين',emoji:'🐉',price:10000),GiftItem(id:'lion',name:'أسد',emoji:'🦁',price:25000)];
class GiftSheet extends StatefulWidget{final String roomId;final void Function(GiftItem gift)? onSent;const GiftSheet({super.key,required this.roomId,this.onSent});@override State<GiftSheet> createState()=>_GiftSheetState();}
class _GiftSheetState extends State<GiftSheet>{String? recipient;int balance=0;@override void initState(){super.initState();_load();}Future<void> _load()async{final u=Supabase.instance.client.auth.currentUser;if(u==null)return;final r=await Supabase.instance.client.from('wallets').select('balance').eq('user_id',u.id).maybeSingle();if(mounted)setState(()=>balance=(r?['balance'] as num?)?.toInt()??0);}Future<void> _send(GiftItem g)async{final target=recipient;if(target==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('اختر مستلم الهدية')));return;}try{await Supabase.instance.client.rpc('send_gift',params:{'p_room_id':widget.roomId,'p_recipient_id':target,'p_gift_id':g.id});await _load();if(mounted){widget.onSent?.call(g);Navigator.pop(context);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تم إرسال '+g.emoji+' '+g.name+' 🔥')));}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر إرسال الهدية: $e')));}}@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Container(padding:const EdgeInsets.all(16),decoration:const BoxDecoration(color:Color(0xFF120805),borderRadius:BorderRadius.vertical(top:Radius.circular(24))),child:Column(mainAxisSize:MainAxisSize.min,children:[Row(children:[const Text('الهدايا 🎁',style:TextStyle(color:Color(0xFFFFD36A),fontSize:20,fontWeight:FontWeight.w900)),const Spacer(),Text(balance.toString()+' 🪙',style:const TextStyle(color:Color(0xFFFFD36A),fontWeight:FontWeight.bold))]),const SizedBox(height:10),TextField(onChanged:(v)=>setState(()=>recipient=v.trim().isEmpty?null:v.trim()),decoration:const InputDecoration(labelText:'ID أو اسم المستخدم للمستلم',prefixIcon:Icon(Icons.person_search))),const SizedBox(height:12),GridView.builder(shrinkWrap:true,itemCount:gifts.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,childAspectRatio:.9,crossAxisSpacing:8,mainAxisSpacing:8),itemBuilder:(_,i){final g=gifts[i];return InkWell(onTap:()=>_send(g),child:Container(decoration:BoxDecoration(color:const Color(0xFF241207),borderRadius:BorderRadius.circular(16),border:Border.all(color:const Color(0xFF6A421A))),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(g.emoji,style:const TextStyle(fontSize:34)),Text(g.name,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:11)),Text(g.price.toString()+' 🪙',style:const TextStyle(color:Color(0xFFFFD36A),fontSize:10))])));}),const SizedBox(height:8)]));}}
